installer-gui-script.script:
function ramGB() {
    return Math.round(parseInt(system.sysctl('hw.memsize')) / (1024 * 1024 * 1024));
}

/* Python: recommend installing if no python.org framework found */
function pythonNeeded() {
    var vers = ['3.14', '3.13', '3.12', '3.11'];
    for (var i = 0; i < vers.length; i++) {
        if (system.files.fileExistsAtPath(
            '/Library/Frameworks/Python.framework/Versions/' + vers[i])) {
            return 0;
        }
    }
    return 1;
}

/* AI model — auto-select based on RAM */
function sel3b()  { return ramGB() < 16 ? 1 : 0; }
function sel7b()  { var r = ramGB(); return (r >= 16 && r < 32)  ? 1 : 0; }
function sel14b() { var r = ramGB(); return (r >= 32 && r < 64)  ? 1 : 0; }
function sel32b() { var r = ramGB(); return (r >= 64 && r < 128) ? 1 : 0; }
function sel72b() { return ramGB() >= 128 ? 1 : 0; }
